static void* AllocChunk(cmsIT8* it8, cmsUInt32Number size);

static
string* StringAlloc(cmsIT8* it8, int max)
{
    string* s = (string*) AllocChunk(it8, sizeof(string));

    s->it8 = it8;
    s->max = MAXSTR;
    s->len = 0;
    s->begin = (char*) AllocChunk(it8, s->max);

    return s;
}
